/* 0095_a_niche_page_reads_its_own_niche.sql, flattened for the Supabase SQL editor. Generated by scripts/flatten-migration.mjs - do not edit this file, edit the migration and run the script again. One statement per line, no line comments, nothing to lose to a newline. The commentary lives in the migration itself. */
create or replace function public.niche_page_listings(p_niche text) returns table ( id uuid, domain_rating integer, organic_traffic integer, country text, services jsonb ) language sql stable security definer set search_path = public as $$ select m.id, m.domain_rating, m.organic_traffic, m.country, coalesce( ( select jsonb_agg( jsonb_build_object( 'type', s.type, 'price_minor', s.price_minor, 'available', s.available ) ) from public.services s where s.website_id = m.id ), '[]'::jsonb ) as services from public.marketplace_listings m where m.status = 'active' and (m.niche = p_niche or p_niche = any(m.secondary_niches)); $$;
comment on function public.niche_page_listings(text) is 'The active listings in one niche, with their services, for /guest-posts/<niche>. Primary or secondary, following 0077 - not marketplace_niche_preview, which still coalesces a missing category to technology.';
revoke all on function public.niche_page_listings(text) from public, anon, authenticated;
grant execute on function public.niche_page_listings(text) to service_role;
